"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["74068"],{245730(n){n.exports=JSON.parse('{"id":14241,"title":"\u0623\u0646\u0634\u0626 \u062E\u0631\u064A\u0637\u0629 \u0630\u0647\u0646\u064A\u0629 \u0639\u0631\u0628\u064A\u0629","description":"\u0623\u0646\u0634\u0626 \u062E\u0631\u064A\u0637\u0629 \u0630\u0647\u0646\u064A\u0629 \u0639\u0631\u0628\u064A\u0629 \u0645\u0631\u0633\u0648\u0645\u0629 \u0628\u062E\u0637 \u0627\u0644\u064A\u062F \u0639\u0644\u0649 \u0648\u0631\u0642 \u0623\u0628\u064A\u0636\u060C\\n\u0628\u0623\u0633\u0644\u0648\u0628 \u0645\u0630\u0643\u0651\u0631\u0627\u062A \u0627\u0644\u0637\u0644\u0627\u0628 \u0627\u0644\u062A\u0639\u0644\u064A\u0645\u064A\u0629\u060C \u0639\u0646 \u0645\u0648\u0636\u0648\u0639: [\u0627\u0643\u062A\u0628 \u0627\u0644\u062F\u0631\u0633].\\n\\n\u0627\u0644\u062A\u0646\u0633\u064A\u0642:\\n- \u0641\u0642\u0627\u0639\u0629 \u0633\u062D\u0627\u0628\u064A\u0629 \u0641\u064A \u0627\u0644\u0645\u0646\u062A\u0635\u0641 \u062A\u062D\u0648\u064A \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0631\u0626\u064A\u0633\u064A.\\n- \u0641\u0631\u0648\u0639 \u0645\u0646\u062D\u0646\u064A\u0629 \u062A\u062E\u0631\u062C \u0645\u0646\u0647\u0627 \u0625\u0644\u0649 \u0641\u0642\u0627\u0639\u0627\u062A \u0641\u0631\u0639\u064A\u0629 \u0645\u0639\u0646\u0648\u0646\u0629 \u0644\u0643\u0644\\n  \u0645\u062D\u0648\u0631: [\u0627\u0643\u062A\u0628 \u0627\u0644\u0641\u0631\u0648\u0639 \u0645\u062B\u0644: \u0627\u0644\u062A\u0639\u0631\u064A\u0641\u060C \u0627\u0644\u0645\u0643\u0648\u0651\u0646\u0627\u062A\u060C \u0627\u0644\u0646\u062A\u0627\u0626\u062C\u060C \u0627\u0644\u0623\u0647\u0645\u064A\u0629].\\n- \u062E\u0637 \u064A\u062F \u0639\u0631\u0628\u064A \u0648\u0627\u0636\u062D \u0648\u0645\u0631\u062A\u0651\u0628 (\u0645\u0646 \u0627\u0644\u064A\u0645\u064A\u0646 \u0644\u0644\u064A\u0633\u0627\u0631)\u060C \u0645\u0639 \u062A\u0645\u064A\u064A\u0632\\n  \u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0627\u0644\u0645\u0647\u0645\u0629 \u0628\u0642\u0644\u0645 \u0623\u0635\u0641\u0631 (\u0647\u0627\u064A\u0644\u0627\u064A\u062A\u0631).\\n- \u0631\u0633\u0648\u0645\u0627\u062A \u0628\u0633\u064A\u0637\u0629 \u0644\u0637\u064A\u0641\u0629 \u0645\u0631\u062A\u0628\u0637\u0629 \u0628\u0627\u0644\u0645\u0648\u0636\u0648\u0639 (\u0623\u0648\u0631\u0627\u0642\u060C \u0634\u0645\u0633\u060C \u0642\u0637\u0631\u0627\u062A).\\n- \u0646\u0635 \u0628\u0627\u0644\u0642\u0644\u0645 \u0627\u0644\u0623\u0632\u0631\u0642\u060C \u0648\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0628\u0627\u0644\u0623\u062D\u0645\u0631\u060C \u0648\u0644\u0645\u0633\u0627\u062A \u062E\u0636\u0631\u0627\u0621 \u0648\u0635\u0641\u0631\u0627\u0621.\\n- \u0635\u0646\u062F\u0648\u0642 \u0635\u063A\u064A\u0631 \u0644\u0644\u0640\\"\u0627\u0644\u062E\u0644\u0627\u0635\u0629\\" \u0641\u064A \u0623\u062D\u062F \u0627\u0644\u0623\u0631\u0643\u0627\u0646.\\n\\n\u0627\u0644\u0623\u0633\u0644\u0648\u0628: \u062F\u0641\u062A\u0631 \u0637\u0627\u0644\u0628 \u0646\u0638\u064A\u0641\u060C \u0623\u0642\u0644\u0627\u0645 \u0645\u0644\u0648\u0651\u0646\u0629\u060C \u0645\u0646\u0638\u0651\u0645 \u0648\u0628\u0633\u064A\u0637\u060C A4 \u0639\u0645\u0648\u062F\u064A.\\n\u0627\u0643\u062A\u0628 \u0643\u0644 \u0627\u0644\u0646\u0635\u0648\u0635 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0628\u0648\u0636\u0648\u062D \u0648\u0625\u0645\u0644\u0627\u0621 \u0635\u062D\u064A\u062D.","owner":"misraoui","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-07-09T01:52:25.127Z"}')}}]);